zenuml
title Transaction with retries
@Actor User
API as Application
@Database Store
User->API.submit(order) {
  try {
    forEach(item in order) {
      if(item.valid) {
        Store.save(item)
      } else if(item.retry) {
        opt(retry) { API.schedule(item) }
      } else {
        API.reject(item)
      }
    }
    par {
      API->Audit: committed
      API->Metrics: count
    }
  } catch(error) {
    API->User: failed
  } finally {
    Store.close()
  }
  return receipt
}

