Client.execute() {
  for(index) {
    Worker.prepare()
  }
  foreach(item) {
    Worker.process(item)
  }
  loop(retry) {
    critical(lock) {
      Store.write()
    }
  }
  while(waiting) {
    Worker.poll()
  }
}

zenuml
title Lifecycle and reply destinations
@Actor Client
Service
Client->Service.create() {
  new Worker(configuration) {
    result = Store.read()
    return result
  }
  if(success) {
    @return
    Service->Client: ready
  } else {
    @reply
    Service->Client: rejected
  }
}

zenuml
Client as Consumer
@Database Database
// Validate the request.
// **Preserve** the source transaction.
Client.validate() {
  // Read the `current` version.
  Version current = Database.read()
  if(current) {
    // The write is *atomic*.
    Database.write(current)
  } else {
    Database.initialize()
  }
  return current
}

zenuml
Orchestrator.run() {
  par {
    section(stage1) {
      A.prepare()
      B.prepare()
    }
    section(stage2) {
      opt(needsCache) {
        Cache.warm()
      }
      Worker.start()
    }
    critical(commit) {
      Store.commit()
    }
  }
}

zenuml
Gateway.handle() {
  try {
    if(primary) {
      Primary.execute()
    } else if(secondary) {
      Secondary.execute()
    } else if(offline) {
      Cache.read()
    } else {
      Reject.send()
    }
  } catch(NetworkError) {
    Retry.schedule()
  } catch(StorageError) {
    Audit.record()
  } finally {
    Gateway.release()
  }
  return status
}

